import{_ as a,o as n,c as p,a2 as e}from"./chunks/framework.D66Xq0Kv.js";const r=JSON.parse('{"title":"树莓派配置","description":"","frontmatter":{"title":"树莓派配置","date":"2018-12-12","categories":["开发工具","操作系统"],"tags":["Linux"]},"headers":[],"relativePath":"开发工具/树莓派配置.md","filePath":"开发工具/树莓派配置.md"}'),t={name:"开发工具/树莓派配置.md"};function i(l,s,o,c,d,h){return n(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="树莓派配置" tabindex="-1">树莓派配置 <a class="header-anchor" href="#树莓派配置" aria-label="Permalink to &quot;树莓派配置&quot;">​</a></h1><p>树莓派配置, 包括常用开发环境及部分实用工具的安装与配置</p><h2 id="安装raspbian系统至sd卡" tabindex="-1">安装raspbian系统至SD卡 <a class="header-anchor" href="#安装raspbian系统至sd卡" aria-label="Permalink to &quot;安装raspbian系统至SD卡&quot;">​</a></h2><p>略</p><h2 id="选择国内仓库源" tabindex="-1">选择国内仓库源 <a class="header-anchor" href="#选择国内仓库源" aria-label="Permalink to &quot;选择国内仓库源&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo sed -i &#39;s#://raspbian.raspberrypi.org#s://mirrors.ustc.edu.cn/raspbian#g&#39; /etc/apt/sources.list</span></span>
<span class="line"><span>sudo sed -i &#39;s#://archive.raspberrypi.org/debian#s://mirrors.ustc.edu.cn/archive.raspberrypi.org/debian#g&#39; /etc/apt/sourceslist.d/raspi.list</span></span></code></pre></div><blockquote><p>参见链接<a href="https://www.jianshu.com/p/67b9e6ebf8a0" title="作者：qcsunny" target="_blank" rel="noreferrer">树莓派—raspbian软件源（全）</a></p></blockquote><h2 id="使用vnc协议无线连接桌面" tabindex="-1">使用VNC协议无线连接桌面 <a class="header-anchor" href="#使用vnc协议无线连接桌面" aria-label="Permalink to &quot;使用VNC协议无线连接桌面&quot;">​</a></h2><p>系统已经默认安装RealVNC,直接启动即可</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vncserver</span></span></code></pre></div><h2 id="使用rdp协议无线连接桌面" tabindex="-1">使用RDP协议无线连接桌面 <a class="header-anchor" href="#使用rdp协议无线连接桌面" aria-label="Permalink to &quot;使用RDP协议无线连接桌面&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install tightvncserver xrdp</span></span></code></pre></div><blockquote><p>安装tightvncserver将会自动卸载realvnc</p></blockquote><h2 id="安装phpmyadmin环境" tabindex="-1">安装phpMyAdmin环境 <a class="header-anchor" href="#安装phpmyadmin环境" aria-label="Permalink to &quot;安装phpMyAdmin环境&quot;">​</a></h2><ol><li><p>安装nginx,php-fpm,mairadb</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install nginx php-fpm mariadb-server</span></span></code></pre></div></li><li><p>配置数据库</p><ul><li>安全设置</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo mysql_secure_installation</span></span></code></pre></div><ul><li>登录</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mysql -uroot -p</span></span></code></pre></div><blockquote><p>报错，错误信息为：ERROR 1698 (28000): Access denied for user &#39;root&#39;@&#39;localhost&#39;</p></blockquote><p>解决方案：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo mysql -uroot -p</span></span>
<span class="line"><span>update mysql.user set authentication_string=PASSWORD(&#39;root&#39;), plugin=&#39;mysql_native_password&#39; where user=&#39;root&#39;;</span></span>
<span class="line"><span>flush privileges;</span></span></code></pre></div></li><li><p>配置nginx以支持php</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo vim /etc/nginx/sites-available/default</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-----------------------------------</span></span>
<span class="line"><span>location / {</span></span>
<span class="line"><span>    index  index.html index.htm index.php default.html default.htm default.php;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>location ~\\.php$ {</span></span>
<span class="line"><span>    fastcgi_pass unix:/run/php/php7.3-fpm.sock;</span></span>
<span class="line"><span>    fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;</span></span>
<span class="line"><span>    include fastcgi_params;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>-----------------------------------</span></span></code></pre></div></li><li><p>配置php以支持mysql</p><ul><li>安装php的mysql扩展</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install php-mysql</span></span></code></pre></div><ul><li>在配置文件中加入php的mysql扩展</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo vim /etc/php/7.3/fpm/php.ini</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-----------------------------------</span></span>
<span class="line"><span>extension=mysqli ;去掉注释</span></span>
<span class="line"><span>-----------------------------------</span></span></code></pre></div></li><li><p>安装phpMyAdmin</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd ~/Downloads</span></span>
<span class="line"><span>wget https://www.phpmyadmin.net/downloads/phpMyAdmin-latest-all-languages.tar.gz</span></span>
<span class="line"><span>tar zxvf phpMyAdmin-latest-all-languages.tar.gz</span></span>
<span class="line"><span>sudo mv phpMyAdmin-*-all-languages /var/www/html/pma</span></span></code></pre></div></li></ol><h2 id="安装tomcat环境" tabindex="-1">安装tomcat环境 <a class="header-anchor" href="#安装tomcat环境" aria-label="Permalink to &quot;安装tomcat环境&quot;">​</a></h2><ol><li><p>安装jdk环境</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install openjdk-8-jdk</span></span></code></pre></div></li><li><p>下载tomcat8.5.42并解压至/usr/local/java目录下</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd ~/Downloads</span></span>
<span class="line"><span>wget https://mirrors.tuna.tsinghua.edu.cn/apache/tomcat/tomcat-8/v8.5.42/bin/apache-tomcat-8.5.42.tar.gz</span></span>
<span class="line"><span>tar zxf apache-tomcat-8.5.42.tar.gz</span></span>
<span class="line"><span>sudo mkdir /usr/local/java</span></span>
<span class="line"><span>sudo mv apache-tomcat-8.5.42 /usr/local/java/tomcat</span></span></code></pre></div></li><li><p>设置开机自启动tomcat</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo vim /etc/rc.local</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-----------------------------------</span></span>
<span class="line"><span>/usr/local/java/tomcat/bin/startup.sh</span></span>
<span class="line"><span># 在exit 0前加入tomcat启动文件</span></span>
<span class="line"><span>-----------------------------------</span></span></code></pre></div></li></ol><h2 id="配置无线静态ip" tabindex="-1">配置无线静态IP <a class="header-anchor" href="#配置无线静态ip" aria-label="Permalink to &quot;配置无线静态IP&quot;">​</a></h2><ol><li><p>编辑dhcpcd.conf文件</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo vim /etc/dhcpcd.conf</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-----------------------------------</span></span>
<span class="line"><span>interface wlan0</span></span>
<span class="line"><span>static ip_address=192.168.0.200/24</span></span>
<span class="line"><span>static routers=192.168.0.1</span></span>
<span class="line"><span>static domain_name_server=114.114.114.114</span></span>
<span class="line"><span>-----------------------------------</span></span></code></pre></div></li></ol><h2 id="安装花生壳实现内网穿透" tabindex="-1">安装花生壳实现内网穿透 <a class="header-anchor" href="#安装花生壳实现内网穿透" aria-label="Permalink to &quot;安装花生壳实现内网穿透&quot;">​</a></h2><ol><li><p>下载安装花生壳</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd ~/Downloads</span></span>
<span class="line"><span>wget http://download.oray.com/peanuthull/embed/phddns_3.0.3_systemd.deb</span></span>
<span class="line"><span>sudo dpkg -i phddns_3.0.3_systemd.deb</span></span></code></pre></div></li></ol><h2 id="安装ftp服务器实现文件共享" tabindex="-1">安装ftp服务器实现文件共享 <a class="header-anchor" href="#安装ftp服务器实现文件共享" aria-label="Permalink to &quot;安装ftp服务器实现文件共享&quot;">​</a></h2><ol><li><p>安装vsftp</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install vsftpd</span></span></code></pre></div></li><li><p>配置vsftp</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo vim /etc/vsftpd.conf</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-----------------------------------</span></span>
<span class="line"><span>write_enable=YES</span></span>
<span class="line"><span>local_umask=022</span></span>
<span class="line"><span>-----------------------------------</span></span></code></pre></div></li><li><p>挂载移动硬盘</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo mount -o uid=pi,gid=pi /dev/sda1 ~/Public</span></span></code></pre></div></li></ol><h2 id="开机后自动推送ip至邮箱" tabindex="-1">开机后自动推送IP至邮箱 <a class="header-anchor" href="#开机后自动推送ip至邮箱" aria-label="Permalink to &quot;开机后自动推送IP至邮箱&quot;">​</a></h2><ol><li><p>安装邮件客户端</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install msmtp mutt</span></span></code></pre></div></li><li><p>配置msmtp</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim .msmtprc</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-----------------------------------</span></span>
<span class="line"><span>account default</span></span>
<span class="line"><span>host smtp.qq.com</span></span>
<span class="line"><span>from luanrzh@qq.com</span></span>
<span class="line"><span>auth plain</span></span>
<span class="line"><span>user luanrzh@qq.com</span></span>
<span class="line"><span>password mfnamealwuktbabi</span></span>
<span class="line"><span>logfile /var/log/msmtp.log</span></span>
<span class="line"><span>-----------------------------------</span></span></code></pre></div><blockquote><p>.msmtprc初始权限会报错：msmtp: /home/pi/.msmtprc: contains secrets and therefore must have no more than user read/write permissions</p></blockquote></li><li><p>修改.msmtprc文件权限</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chmod 600 .msmtprc</span></span></code></pre></div></li><li><p>配置mutt</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim .muttrc</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-----------------------------------</span></span>
<span class="line"><span>set sendmail=&quot;/usr/bin/msmtp&quot;</span></span>
<span class="line"><span>set use_from=yes</span></span>
<span class="line"><span>set from=&quot;luanrzh@qq.com&quot;</span></span>
<span class="line"><span>set realname=&quot;pi&quot;</span></span>
<span class="line"><span>set editor=&quot;vim&quot;</span></span>
<span class="line"><span>-----------------------------------</span></span></code></pre></div></li><li><p>新增&quot;获取IP并发邮件&quot;的<a href="http://shumeipai.nxez.com/2014/03/18/let-raspberry-pi-ip-address-is-automatically-reported-to-the-mailbox.html" target="_blank" rel="noreferrer">脚本</a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim send-ip-mail.sh</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-----------------------------------</span></span>
<span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span># check network availability</span></span>
<span class="line"><span>while true</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>TIMEOUT=5</span></span>
<span class="line"><span>SITE_TO_CHECK=&quot;https://www.126.com/&quot;</span></span>
<span class="line"><span>RET_CODE=\`curl -I -s --connect-timeout $TIMEOUT $SITE_TO_CHECK -w %{http_code} | tail -n1\`</span></span>
<span class="line"><span>if [ &quot;x$RET_CODE&quot; = &quot;x200&quot; ]; then</span></span>
<span class="line"><span>echo &quot;Network OK, will send mail...&quot;</span></span>
<span class="line"><span>break</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>echo &quot;Network not ready, wait...&quot;</span></span>
<span class="line"><span>sleep 1s</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span></span></span>
<span class="line"><span># get the IP address of eth0, e.g. &quot;192.168.16.5&quot;</span></span>
<span class="line"><span>ETH0_IP_ADDR=\`ifconfig eth0 | sed -n &quot;2,2p&quot; | awk &#39;{print substr($2,1)}&#39;\`</span></span>
<span class="line"><span>WLAN0_IP_ADDR=\`ifconfig wlan0 | sed -n &quot;2,2p&quot; | awk &#39;{print substr($2,1)}&#39;\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span># send the Email</span></span>
<span class="line"><span>echo -e &quot;有线:\${ETH0_IP_ADDR}\\n无线:\${WLAN0_IP_ADDR}&quot; | mutt -s &quot; 树莓派IP&quot; luanrzh@qq.com</span></span>
<span class="line"><span>-----------------------------------</span></span></code></pre></div></li><li><p>编写 开机运行脚本</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo vim  /etc/rc.local</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-----------------------------------</span></span>
<span class="line"><span>#...</span></span>
<span class="line"><span>/home/pi/send-ip-mail.sh &gt;&gt; /home/pi/send-ip-mail.log 2&gt;&amp;1</span></span>
<span class="line"><span>exit 0</span></span>
<span class="line"><span>-----------------------------------</span></span></code></pre></div><blockquote><p>上述脚本是以root用户执行，当前/root目录下还没有msmtp和mutt的配置文件</p></blockquote></li><li><p>复制配置文件至/root目录下</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo cp .msmtprc /root</span></span>
<span class="line"><span>sudo cp .muttrc /root</span></span></code></pre></div></li></ol>`,25)])])}const g=a(t,[["render",i]]);export{r as __pageData,g as default};
